// Normalize Remote OK jobs
const items = $input.all();
const output = [];

for (const item of items) {
  const data = item.json;
  // RemoteOK returns array; first item is metadata
  if (!Array.isArray(data)) continue;

  for (const job of data) {
    if (!job.id || !job.position) continue;
    output.push({
      json: {
        job_title: job.position || '',
        company: job.company || '',
        job_url: job.url || `https://remoteok.com/remote-jobs/${job.id}`,
        source: 'Remote OK',
        location_text: job.location || 'Worldwide',
        salary: job.salary || '',
        description: (job.description || '') + ' ' + (job.tags ? job.tags.join(' ') : ''),
        posted_date: job.date || new Date().toISOString(),
        tags: job.tags ? job.tags.join(', ') : '',
        job_id: 'remoteok-' + job.id
      }
    });
  }
}

return output;

// Normalize Remotive jobs
const items = $input.all();
const output = [];

for (const item of items) {
  const data = item.json;
  const jobs = data.jobs || [];

  for (const job of jobs) {
    output.push({
      json: {
        job_title: job.title || '',
        company: job.company_name || '',
        job_url: job.url || '',
        source: 'Remotive',
        location_text: job.candidate_required_location || 'Worldwide',
        salary: job.salary || '',
        description: (job.description || '').replace(/<[^>]*>/g, ' ').substring(0, 3000),
        posted_date: job.publication_date || new Date().toISOString(),
        tags: job.tags ? job.tags.join(', ') : '',
        job_id: 'remotive-' + job.id
      }
    });
  }
}

return output;

// Parse and normalize WWR RSS
const items = $input.all();
const output = [];

for (const item of items) {
  const xml = item.json.data || item.json;
  const xmlStr = typeof xml === 'string' ? xml : JSON.stringify(xml);

  // Simple regex-based RSS parser
  const itemMatches = xmlStr.match(/<item>([\s\S]*?)<\/item>/g) || [];

  for (const block of itemMatches) {
    const extract = (tag) => {
      const m = block.match(new RegExp(`<${tag}[^>]*><!\\[CDATA\\[([\\s\\S]*?)\\]\\]><\/${tag}>|<${tag}[^>]*>([\\s\\S]*?)<\/${tag}>`));
      return m ? (m[1] || m[2] || '').trim() : '';
    };

    const title = extract('title');
    const link = extract('link');
    const description = extract('description');
    const pubDate = extract('pubDate');
    const company = title.includes(':') ? title.split(':')[0].trim() : '';
    const jobTitle = title.includes(':') ? title.split(':').slice(1).join(':').trim() : title;

    if (!title) continue;

    output.push({
      json: {
        job_title: jobTitle,
        company: company,
        job_url: link,
        source: 'We Work Remotely',
        location_text: 'Worldwide',
        salary: '',
        description: description.replace(/<[^>]*>/g, ' ').substring(0, 3000),
        posted_date: pubDate || new Date().toISOString(),
        tags: '',
        job_id: 'wwr-' + Buffer.from(link).toString('base64').substring(0, 20)
      }
    });
  }
}

return output;

// Parse and normalize Himalayas RSS
const items = $input.all();
const output = [];

for (const item of items) {
  const xml = item.json.data || item.json;
  const xmlStr = typeof xml === 'string' ? xml : JSON.stringify(xml);

  const itemMatches = xmlStr.match(/<item>([\s\S]*?)<\/item>/g) || [];

  for (const block of itemMatches) {
    const extract = (tag) => {
      const m = block.match(new RegExp(`<${tag}[^>]*><!\\[CDATA\\[([\\s\\S]*?)\\]\\]><\/${tag}>|<${tag}[^>]*>([\\s\\S]*?)<\/${tag}>`));
      return m ? (m[1] || m[2] || '').trim() : '';
    };

    const title = extract('title');
    const link = extract('link');
    const description = extract('description');
    const pubDate = extract('pubDate');
    const author = extract('author');

    if (!title) continue;

    output.push({
      json: {
        job_title: title,
        company: author || '',
        job_url: link,
        source: 'Himalayas',
        location_text: 'Worldwide',
        salary: '',
        description: description.replace(/<[^>]*>/g, ' ').substring(0, 3000),
        posted_date: pubDate || new Date().toISOString(),
        tags: '',
        job_id: 'himalayas-' + Buffer.from(link).toString('base64').substring(0, 20)
      }
    });
  }
}

return output;

// Parse and normalize Dynamite Jobs RSS
const items = $input.all();
const output = [];

for (const item of items) {
  const xml = item.json.data || item.json;
  const xmlStr = typeof xml === 'string' ? xml : JSON.stringify(xml);

  const itemMatches = xmlStr.match(/<item>([\s\S]*?)<\/item>/g) || [];

  for (const block of itemMatches) {
    const extract = (tag) => {
      const m = block.match(new RegExp(`<${tag}[^>]*><!\\[CDATA\\[([\\s\\S]*?)\\]\\]><\/${tag}>|<${tag}[^>]*>([\\s\\S]*?)<\/${tag}>`));
      return m ? (m[1] || m[2] || '').trim() : '';
    };

    const title = extract('title');
    const link = extract('link');
    const description = extract('description');
    const pubDate = extract('pubDate');

    if (!title) continue;

    const parts = title.split(' at ');
    const jobTitle = parts[0] ? parts[0].trim() : title;
    const company = parts[1] ? parts[1].trim() : '';

    output.push({
      json: {
        job_title: jobTitle,
        company: company,
        job_url: link,
        source: 'Dynamite Jobs',
        location_text: 'Worldwide',
        salary: '',
        description: description.replace(/<[^>]*>/g, ' ').substring(0, 3000),
        posted_date: pubDate || new Date().toISOString(),
        tags: '',
        job_id: 'dynamite-' + Buffer.from(link).toString('base64').substring(0, 20)
      }
    });
  }
}

return output;

// Normalize YC Work at Startup - parse HTML response
const items = $input.all();
const output = [];

for (const item of items) {
  const html = typeof item.json === 'string' ? item.json : (item.json.data || '');

  // Extract job postings from JSON-LD or structured data if available
  const jsonLdMatches = html.match(/<script type="application\/ld\+json">[\s\S]*?<\/script>/g) || [];

  for (const block of jsonLdMatches) {
    try {
      const jsonStr = block.replace(/<script[^>]*>/, '').replace(/<\/script>/, '');
      const data = JSON.parse(jsonStr);
      if (data['@type'] === 'JobPosting') {
        output.push({
          json: {
            job_title: data.title || '',
            company: data.hiringOrganization?.name || '',
            job_url: data.url || data.sameAs || '',
            source: 'YC Work at Startup',
            location_text: data.jobLocation?.address || 'Worldwide',
            salary: data.baseSalary ? JSON.stringify(data.baseSalary) : '',
            description: (data.description || '').replace(/<[^>]*>/g, ' ').substring(0, 3000),
            posted_date: data.datePosted || new Date().toISOString(),
            tags: data.occupationalCategory || '',
            job_id: 'yc-' + Buffer.from((data.url || data.title || '')).toString('base64').substring(0, 20)
          }
        });
      }
    } catch(e) {}
  }
}

// If nothing parsed, return empty
return output.length > 0 ? output : [];

// Keyword filter - keep jobs matching target keywords
const items = $input.all();

const REQUIRED_KEYWORDS = [
  'async remote', 'asynchronous remote', 'worldwide remote', 'global remote',
  'work from anywhere', 'remote data analyst', 'remote data scientist',
  'remote ai marketing', 'remote marketing analyst', 'remote growth analyst',
  'remote bi analyst', 'remote automation', 'remote ai workflow',
  'data analyst', 'data scientist', 'business intelligence', 'bi analyst',
  'marketing analyst', 'growth analyst', 'performance marketing',
  'ai marketing', 'ai automation', 'ai workflow', 'martech analyst',
  'creative strategist', 'analytics', 'machine learning', 'sql',
  'tableau', 'power bi', 'looker', 'python analyst'
];

const output = [];

for (const item of items) {
  const job = item.json;
  const searchText = [
    job.job_title || '',
    job.description || '',
    job.tags || ''
  ].join(' ').toLowerCase();

  const matches = REQUIRED_KEYWORDS.some(kw => searchText.includes(kw.toLowerCase()));

  if (matches) {
    output.push(item);
  }
}

return output;

// Deduplicate: remove jobs already in Google Sheets
const jobItems = $input.item;
// This node receives merged data from both branches
// We need to handle this differently - get all items
const allItems = $input.all();

// Separate existing jobs from new jobs based on source
// Items from Get Existing Jobs have job_url as a column
const existingUrls = new Set();
const existingKeys = new Set();
const newJobs = [];

// First pass: collect existing job URLs from sheets
for (const item of allItems) {
  if (item.json.job_url && item.json.source === undefined && item.json.date_found) {
    // This is from the Google Sheet (has date_found but not source)
    existingUrls.add(item.json.job_url);
    if (item.json.company && item.json.job_title) {
      existingKeys.add((item.json.company + '|' + item.json.job_title).toLowerCase());
    }
  }
}

// Second pass: filter new jobs
for (const item of allItems) {
  if (item.json.source !== undefined) {
    // This is a new job
    const url = item.json.job_url || '';
    const key = ((item.json.company || '') + '|' + (item.json.job_title || '')).toLowerCase();

    if (!existingUrls.has(url) && !existingKeys.has(key) && url) {
      newJobs.push(item);
    }
  }
}

return newJobs;

// Taiwan eligibility hard filter
const items = $input.all();
const output = [];

const REJECT_PATTERNS = [
  'us only', 'usa only', 'united states only', 'us residents only',
  'canada only', 'canadian only', 'uk only', 'united kingdom only',
  'eu only', 'europe only', 'european union only', 'australia only',
  'must be based in', 'must live in', 'must reside in',
  'must be authorized to work in', 'authorized to work in the us',
  'authorized to work in the uk', 'must have work authorization',
  'local work permit required', 'work permit required',
  'hybrid', 'on-site', 'onsite', 'on site', 'office required',
  'in-office', 'in office', 'must commute',
  'remote within country', 'domestic remote', 'local remote',
  'us time zone required', 'must work us hours', 'must work est',
  'must work pst', 'fixed us business hours', 'fixed eu hours',
  'must work cet', 'must work gmt', '9-5 est required',
  '9-5 pst required', 'no international', 'us-based only',
  'permanently authorized to work in the us'
];

const ALLOW_PATTERNS = [
  'worldwide remote', 'work from anywhere', 'global remote',
  'anywhere in the world', 'apac', 'international contractors',
  'contractor', 'b2b', 'deel', 'remote.com', 'oyster', 'oysterhr',
  'eor', 'employer of record', 'remote first', 'distributed team',
  'fully distributed', 'globally distributed', 'all time zones',
  'flexible hours', 'async', 'asynchronous'
];

for (const item of items) {
  const job = item.json;
  const searchText = [
    job.job_title || '',
    job.description || '',
    job.location_text || '',
    job.tags || ''
  ].join(' ').toLowerCase();

  const hasReject = REJECT_PATTERNS.some(p => searchText.includes(p));
  const hasAllow = ALLOW_PATTERNS.some(p => searchText.includes(p));

  // Hard reject
  if (hasReject && !hasAllow) {
    continue;
  }

  output.push({
    json: {
      ...job,
      hard_filter_passed: true,
      has_allow_signal: hasAllow,
      date_found: new Date().toISOString().split('T')[0]
    }
  });
}

return output;

// Parse AI response and merge with job data
const items = $input.all();
const output = [];

for (const item of items) {
  try {
    const aiResponse = item.json;
    const content = aiResponse.choices?.[0]?.message?.content || '{}';

    // Parse JSON response
    let aiResult;
    try {
      aiResult = JSON.parse(content);
    } catch(e) {
      // Try to extract JSON from response
      const jsonMatch = content.match(/\{[\s\S]*\}/);
      aiResult = jsonMatch ? JSON.parse(jsonMatch[0]) : {};
    }

    // Get the original job data passed through
    const jobData = item.json._job || {};

    output.push({
      json: {
        ...jobData,
        taiwan_eligible: aiResult.taiwan_eligible || 'unclear',
        taiwan_reason: aiResult.reason || '',
        location_risk: aiResult.location_risk || 'medium',
        timezone_risk: aiResult.timezone_risk || 'medium',
        contractor_possible: aiResult.contractor_possible || 'unclear',
        ai_decision: aiResult.decision || 'manual_check'
      }
    });
  } catch(e) {
    // On error, keep job as unclear
    output.push({
      json: {
        ...item.json,
        taiwan_eligible: 'unclear',
        taiwan_reason: 'AI check failed: ' + e.message,
        location_risk: 'medium',
        timezone_risk: 'medium',
        contractor_possible: 'unclear',
        ai_decision: 'manual_check'
      }
    });
  }
}

return output;

// Async level filter and scoring
const items = $input.all();
const output = [];

const ASYNC_HIGH = [
  'async', 'asynchronous', 'no meetings', 'fully async',
  'async-first', 'async first', 'low meeting'
];
const ASYNC_MEDIUM = [
  'flexible hours', 'flexible schedule', 'flexible working',
  'own schedule', 'work when you want', 'distributed team',
  'all time zones', 'across time zones', 'remote first', 'remote-first'
];
const ASYNC_LOW = [
  'some overlap', 'minimal meetings', 'few meetings'
];
const ASYNC_REJECT = [
  'strict 9 to 5', 'strict 9-5', 'fixed us hours', 'fixed est hours',
  'fixed pst hours', 'fixed cet hours', 'daily live calls required',
  'must overlap full business day', 'required overlap'
];

const ROLE_HIGH = [
  'data analyst', 'data scientist', 'junior data scientist',
  'business intelligence', 'bi analyst', 'marketing analyst',
  'performance marketing analyst', 'growth analyst', 'growth hacker',
  'ai marketing', 'ai automation', 'ai workflow', 'martech analyst',
  'analytics engineer', 'data engineer', 'ml engineer',
  'machine learning', 'marketing data', 'revenue analyst'
];
const ROLE_MEDIUM = [
  'digital marketing', 'content analyst', 'seo analyst', 'ppc analyst',
  'paid media analyst', 'campaign analyst', 'social media analyst',
  'product analyst', 'operations analyst', 'reporting analyst',
  'insights analyst', 'crm analyst', 'email marketing',
  'automation specialist', 'workflow specialist', 'no-code'
];

for (const item of items) {
  const job = item.json;
  const text = [
    job.job_title || '',
    job.description || '',
    job.tags || ''
  ].join(' ').toLowerCase();

  // Async rejection check
  if (ASYNC_REJECT.some(p => text.includes(p))) {
    continue;
  }

  // Determine async level
  let asyncLevel = 'none';
  let asyncScore = 0;
  if (ASYNC_HIGH.some(p => text.includes(p))) {
    asyncLevel = 'high';
    asyncScore = 25;
  } else if (ASYNC_MEDIUM.some(p => text.includes(p))) {
    asyncLevel = 'medium';
    asyncScore = 20;
  } else if (ASYNC_LOW.some(p => text.includes(p))) {
    asyncLevel = 'low';
    asyncScore = 15;
  } else {
    asyncLevel = 'unknown';
    asyncScore = 10;
  }

  // Determine role fit
  let roleCategory = 'other';
  let roleScore = 0;
  const title = (job.job_title || '').toLowerCase();
  if (ROLE_HIGH.some(p => title.includes(p) || text.includes(p))) {
    roleCategory = 'primary';
    roleScore = 25;
  } else if (ROLE_MEDIUM.some(p => title.includes(p) || text.includes(p))) {
    roleCategory = 'adjacent';
    roleScore = 15;
  } else {
    roleScore = 0;
  }

  // Taiwan eligibility score
  let taiwanScore = 0;
  const eli = (job.taiwan_eligible || '').toLowerCase();
  const desc = (job.description || '').toLowerCase();
  if (eli === 'yes' || desc.includes('worldwide') || desc.includes('work from anywhere') || desc.includes('global remote')) {
    taiwanScore = 40;
  } else if (desc.includes('apac')) {
    taiwanScore = 30;
  } else if (eli === 'unclear') {
    taiwanScore = 20;
  } else {
    taiwanScore = 0;
  }

  // Salary score
  let salaryScore = 0;
  const salaryText = (job.salary || '').toString();
  const salaryNums = salaryText.match(/\d+/);
  if (salaryNums) {
    const num = parseInt(salaryNums[0]);
    // Detect if annual or monthly
    const isAnnual = salaryText.includes('year') || salaryText.includes('annual') || salaryText.includes('yr') || num > 10000;
    const monthly = isAnnual ? num / 12 : num;
    if (monthly >= 5000) salaryScore = 25;
    else if (monthly >= 3000) salaryScore = 15;
    else salaryScore = 10;
  } else if (salaryText.length > 2) {
    salaryScore = 10;
  }

  const totalScore = taiwanScore + asyncScore + roleScore + salaryScore;

  // Why good fit summary
  const whyFit = [];
  if (roleScore >= 25) whyFit.push('Strong role match');
  if (taiwanScore >= 40) whyFit.push('Clearly worldwide eligible');
  if (asyncScore >= 25) whyFit.push('Fully async');
  if (salaryScore >= 25) whyFit.push('High salary');
  if (job.contractor_possible === 'yes') whyFit.push('Contractor friendly');

  output.push({
    json: {
      ...job,
      async_level: asyncLevel,
      role_category: roleCategory,
      score: totalScore,
      why_good_fit: whyFit.join(', ') || 'Matches search criteria'
    }
  });
}

return output;

// Write rejected jobs
const items = $input.all();
return items.map(item => ({
  json: {
    ...item.json,
    date_rejected: new Date().toISOString().split('T')[0],
    reason: item.json.ai_decision === 'reject' ? 
      'AI: ' + (item.json.taiwan_reason || 'Not Taiwan eligible') :
      'Score below 70 (' + (item.json.score || 0) + ')'
  }
}));

// Attach cover letter to job data
const items = $input.all();
return items.map(item => {
  const coverLetter = item.json.choices?.[0]?.message?.content || '';
  return {
    json: {
      ...item.json._job,
      cover_letter_draft: coverLetter
    }
  };
});

// Build daily digest email
const items = $input.all();
const allJobs = items[0]?.json?.all_jobs || [];

// Sort by score descending
allJobs.sort((a, b) => (b.score || 0) - (a.score || 0));

// Separate categories
const topJobs = allJobs.filter(j => (j.score || 0) >= 85 && j.taiwan_eligible !== 'no');
const goodJobs = allJobs.filter(j => (j.score || 0) >= 70 && (j.score || 0) < 85 && j.taiwan_eligible !== 'no');
const manualJobs = allJobs.filter(j => j.taiwan_eligible === 'unclear' && (j.score || 0) >= 70);
const rejectedJobs = allJobs.filter(j => j.ai_decision === 'reject' || (j.score || 0) < 70);

// Count rejection reasons
const usOnly = rejectedJobs.filter(j => (j.taiwan_reason || '').toLowerCase().includes('us')).length;
const euOnly = rejectedJobs.filter(j => (j.taiwan_reason || '').toLowerCase().includes('eu') || (j.taiwan_reason || '').toLowerCase().includes('europe')).length;
const hybrid = rejectedJobs.filter(j => (j.taiwan_reason || '').toLowerCase().includes('hybrid') || (j.taiwan_reason || '').toLowerCase().includes('onsite')).length;
const timezone = rejectedJobs.filter(j => j.timezone_risk === 'high').length;

const formatJob = (job, idx) => `${idx}. ${job.job_title}
   Company: ${job.company}
   Score: ${job.score}/100
   Taiwan eligible: ${job.taiwan_eligible} | Reason: ${job.taiwan_reason || 'N/A'}
   Async level: ${job.async_level}
   Timezone risk: ${job.timezone_risk}
   Salary: ${job.salary || 'Not listed'}
   Why it fits Jerry: ${job.why_good_fit}
   Apply: ${job.job_url}`;

let body = `=== Daily Taiwan Eligible Async Remote Jobs ===\n`;
body += `Date: ${new Date().toLocaleDateString('en-US', { timeZone: 'Asia/Taipei', year: 'numeric', month: 'long', day: 'numeric' })}\n`;
body += `Total new jobs found: ${allJobs.length}\n\n`;

if (topJobs.length > 0) {
  body += `--- TOP JOBS (Score 85+) ---\n\n`;
  topJobs.slice(0, 10).forEach((job, i) => {
    body += formatJob(job, i + 1) + '\n\n';
  });
}

if (goodJobs.length > 0) {
  body += `--- GOOD JOBS (Score 70-84) ---\n\n`;
  goodJobs.slice(0, 5).forEach((job, i) => {
    body += formatJob(job, i + 1) + '\n\n';
  });
}

if (manualJobs.length > 0) {
  body += `--- MANUAL CHECK NEEDED ---\n`;
  body += `These jobs have high scores but unclear Taiwan eligibility:\n\n`;
  manualJobs.slice(0, 5).forEach((job, i) => {
    body += `${i + 1}. ${job.job_title} at ${job.company} (Score: ${job.score})\n`;
    body += `   Reason unclear: ${job.taiwan_reason || 'N/A'}\n`;
    body += `   URL: ${job.job_url}\n\n`;
  });
}

body += `--- REJECTED SUMMARY ---\n`;
body += `Total rejected: ${rejectedJobs.length}\n`;
body += `- US only: ${usOnly}\n`;
body += `- EU only: ${euOnly}\n`;
body += `- Hybrid/onsite: ${hybrid}\n`;
body += `- Timezone risk: ${timezone}\n`;

return [{
  json: {
    digest_text: body,
    subject: `Taiwan Job Hunt - ${topJobs.length} top jobs, ${goodJobs.length} good jobs | ${new Date().toLocaleDateString('en-US', { timeZone: 'Asia/Taipei' })}`,
    top_jobs_count: topJobs.length,
    total_jobs: allJobs.length
  }
}];

